starterCode.css:
body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  background: #FDF8F0;
  max-width: 600px;
  margin: 40px auto;
  padding: 20px;
}
h1 {
  text-align: center;
  color: #3D2B1F;
}
.search-box {
  display: flex;
  gap: 8px;
  margin-bottom: 24px;
}
#searchInput {
  flex: 1;
  padding: 10px 16px;
  border: 2px solid #D4C5A9;
  border-radius: 8px;
  font-size: 16px;
  outline: none;
}
#searchInput:focus {
  border-color: #C9A96E;
}
#searchBtn {
  padding: 10px 24px;
  background: #8B2E2E;
  color: #fff;
  border: none;
  border-radius: 8px;
  font-size: 16px;
  cursor: pointer;
}
#searchBtn:hover {
  background: #C94545;
}
#results {
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.result-item {
  display: flex;
  gap: 16px;
  align-items: center;
  background: #FFFDF7;
  border: 1px solid #E8DDCC;
  border-radius: 12px;
  padding: 16px;
}
.result-item img {
  width: 80px;
  height: 80px;
  border-radius: 8px;
  object-fit: cover;
}
.result-info h3 {
  margin: 0 0 4px 0;
  color: #3D2B1F;
  font-size: 16px;
}
.result-info p {
  margin: 0;
  color: #6B5A4E;
  font-size: 14px;
}

